def main():
    k = int(sys.stdin.readline().strip())
    q = sys.stdin.readline().strip()

    if len(q) < k:
        print("NO")
        return

    # Check if we can have distinct starting characters
    if len(set(q)) < k:
        print("NO")
        return

    # Create the sequence
    sequence = [''] * k
    used_chars = set()

    for i in range(len(q)):
        char = q[i]
        if char not in used_chars:
            sequence[i % k] += char
            used_chars.add(char)
        else:
            sequence[i % k] += char

    print("YES")
    for s in sequence:
        print(s)

