    if len(set(q)) < k:
        print("NO")
        return

    # Create the sequence
    sequence = [''] * k
    used_chars = set()

    # Distribute characters into the sequence
    for i in range(k):
        if i < len(q):
            sequence[i] += q[i]
            used_chars.add(q[i])

    # Fill the rest of the sequence
    for i in range(k, len(q)):
