            if q[i] not in sequence[j]:
                sequence[j] += q[i]
                found = True
                break
        if not found:
            print("NO")
            return

    # Ensure all strings start with distinct characters
    if len(set(s[0] for s in sequence)) != k:
        print("NO")
        return

